// getSubscribedEvents(): subscribe form events unconditionally
'onApiBlueprintResolved' => ['onApiBlueprintResolved', 0],   // Admin2: adjust the form definition
'onAdminSave'            => ['onAdminSave', 0],              // both Admins: adjust values being saved
// The event carries context ('plugin', 'theme', 'page', 'account'), the
// plugin or theme name (or template for pages), and the serialized `fields`.

// In onThemeInitialized (theme) or onPluginsInitialized (plugin), not behind isAdmin():
if (method_exists(\Grav\Common\Data\Blueprint::class, 'addAllowedDynamicCallable')) {
    \Grav\Common\Data\Blueprint::addAllowedDynamicCallable(self::class . '::categoryOptions');
}

// HTML only
$page = $this->grav['page'] ?? null;
if (!$page || !method_exists($page, 'templateFormat') || $page->templateFormat() !== 'html') { return false; }
// Privacy signals
if (($_SERVER['HTTP_DNT'] ?? '') === '1' || in_array($_SERVER['HTTP_SEC_GPC'] ?? '', ['1', '?1'], true)) { return false; }
// Staff (Grav 1.7 admin.* and Grav 2 api.*)
if ($user->authenticated && ($user->authorize('admin.login') || $user->authorize('admin.super')
    || $user->authorize('api.access') || $user->authorize('api.super'))) { return false; }

// Plugin: allow its own safe function inside page content
public function onBuildTwigSandboxPolicy(Event $event): void
{
    $functions = $event['functions'];
    $functions[] = 'example_gallery';
    $event['functions'] = $functions;
}

// Only needed WITHOUT the component-library plugin. In your theme class:
public static function getSubscribedEvents(): array
{
    return ['onThemeInitialized' => ['onThemeInitialized', 0]];
}
public function onThemeInitialized(): void
{
    if (method_exists(\Grav\Common\Data\Blueprint::class, 'addAllowedDynamicCallable')) {
        \Grav\Common\Data\Blueprint::addAllowedDynamicCallable(self::class . '::authorOptions');
    }
}
// ...then copy authorOptions() from component-library.php and change page.yaml's
// data-options@ to '\Grav\Theme\YourTheme::authorOptions'.

